package com.example.crm.task; import org.springframework.stereotype.Service; import java.util.*; import java.time.LocalDate;
@Service public class TaskService {final TaskRepository repo;final TaskMapper mapper; public TaskService(TaskRepository r,TaskMapper m){repo=r;mapper=m;} public List<TaskDto> all(){return repo.findAll().stream().map(mapper::toDto).toList();} public TaskDto one(UUID id){return repo.findById(id).map(mapper::toDto).orElseThrow();} public TaskDto create(String t,LocalDate d,UUID c,UUID deal){return mapper.toDto(repo.save(mapper.toEntity(t,d,c,deal)));} public TaskDto update(UUID id,String t,LocalDate d,UUID c,UUID deal){var x=repo.findById(id).orElseThrow();mapper.update(x,t,d,c,deal);return mapper.toDto(repo.save(x));} public TaskDto complete(UUID id){var x=repo.findById(id).orElseThrow();x.setCompleted(true);return mapper.toDto(repo.save(x));} public void delete(UUID id){if(!repo.existsById(id))throw new NoSuchElementException();repo.deleteById(id);} }
